import type { HourCell } from "@/lib/generator/types";
import type { Weather } from "@/lib/generator/rules";
import type { TripForecast } from "./trip";

/**
 * OpenWeather One Call 4.0 — the mapping layer.
 *
 * ⚠️ 4.0 is a RESTRUCTURED API, not a version bump of 3.0. Where 3.0 returned
 * current + hourly + daily in one payload, 4.0 splits them across endpoints:
 *
 *   /data/4.0/onecall/current
 *   /data/4.0/onecall/timeline/1day      ← "1day", NOT "daily"
 *   /data/4.0/onecall/timeline/1h        ← "1h",   NOT "hourly"
 *
 * Guessing `daily`/`hourly` returns a JSON 404 that is indistinguishable from a
 * missing subscription, which is its own trap. See the plan for the full
 * archaeology.
 *
 * ⚠️ Pure mapping only — no `fetch` in this file. That is what makes it testable
 * against captured fixtures, and it is how `open-meteo.ts` is already split.
 */

/**
 * The provider's hard caps, MEASURED against the live API rather than read off a
 * docs page: `cnt` above either value is silently ignored.
 *
 * Both are load-bearing. `DAILY_MAX` is the trip horizon — Open-Meteo gave 16,
 * so trips 11–16 days out newly fall past it and `beyondHorizon` stops being an
 * edge case.
 */
export const DAILY_MAX = 10;

/**
 * ⚠️ 20 hours is SHORTER than a day. Open-Meteo gave 24.
 *
 * So `restOfDay` can end before the day does — open the app around 01:00 and the
 * last few hours of the evening are missing, which slightly weakens the
 * "peak still ahead" high/low and the later-advice line.
 *
 * ⚠️ ACCEPTED DELIBERATELY (user, 2026-08-28) AND MARKED AS CHANGEABLE. The
 * affected window is roughly 00:00–04:00 local, when nobody is choosing an
 * outfit, and the daily block's `temp.max`/`temp.min` remains a sound fallback.
 * **To change it:** page a second batch with `start`/`cnt` (the response carries
 * `prev`/`next` links) at the cost of one more call per city per day. Nothing
 * else in the pipeline needs to change — `restOfDay` simply gets longer.
 */
export const HOURLY_MAX = 20;

/** One entry of a `timeline/*` or `current` response. */
type OwmCell = {
  dt: number;
  temp?: number | { day?: number; min?: number; max?: number };
  feels_like?: number | { day?: number };
  weather?: { id: number; main?: string; description?: string }[];
};

type OwmResponse = {
  timezone?: string;
  timezone_offset?: number;
  data?: OwmCell[];
};

export type OneCallBundle = {
  current: OwmResponse;
  hourly: OwmResponse;
  daily: OwmResponse;
};

/**
 * unix `dt` + `timezone_offset` → the wall clock AT THE LOCATION.
 *
 * ⚠️ The sharpest edge in this swap. Open-Meteo was fetched with
 * `timezone=auto`, so it returned local ISO strings and `open-meteo.ts` could
 * compare them as plain strings. One Call returns UTC epochs plus an offset in
 * seconds, so the local clock has to be derived — and every hour window
 * downstream (`planningTempFor`, `occasionWindow`, `laterAdvice`) reads
 * `HourCell.hh` as a LOCAL hour.
 *
 * Shifting the epoch and then reading it in UTC is what produces the local wall
 * clock; using local `getHours()` would give the SERVER's timezone, which on
 * Vercel is UTC and in the simulator is whatever the laptop is set to.
 */
export function localParts(dt: number, offsetSec: number): { date: string; hh: string; hour: number } {
  const shifted = new Date((dt + offsetSec) * 1000);
  const iso = shifted.toISOString();
  return { date: iso.slice(0, 10), hh: iso.slice(11, 16), hour: shifted.getUTCHours() };
}

/**
 * OpenWeather condition ids: 2xx thunderstorm, 3xx drizzle, 5xx rain, 6xx snow,
 * 7xx atmosphere, 800 clear, 80x cloud.
 *
 * ⚠️ Nothing transfers from Open-Meteo's WMO codes — a silently-empty rain set
 * means the rain guard never fires and nobody notices until it rains.
 *
 * ⚠️ Snow (6xx) is deliberately EXCLUDED, matching what `RAIN_CODES` did: the
 * flag drives "take a shell", which is not the advice for snow. A range test
 * rather than an enumerated set, so a condition id we have never seen cannot
 * slip through as "not rain".
 */
export function isRainId(id: number): boolean {
  const band = Math.floor(id / 100);
  return band === 2 || band === 3 || band === 5;
}

/** Kept to the same four strings the UI already renders and truncates. */
function conditionFor(id: number): string {
  if (isRainId(id)) return "Rain";
  if (id === 800) return "Clear";
  if (id === 801 || id === 802) return "Partly cloudy";
  if (id >= 600 && id < 700) return "Snow";
  return "Overcast";
}

function idOf(cell: OwmCell): number {
  return cell.weather?.[0]?.id ?? 800;
}

function scalarTemp(v: OwmCell["temp"]): number | undefined {
  return typeof v === "number" ? v : v?.day;
}

/**
 * The daily drop's shape, from the three One Call responses.
 *
 * `nowDt` defaults to the `current` record's own timestamp, which is the
 * provider's clock rather than ours — the same choice `open-meteo.ts` made, and
 * the reason both are testable without stubbing time.
 */
export function mapOneCall(
  bundle: OneCallBundle,
  nowDt?: number,
): {
  tempC: number;
  feelsLikeC: number;
  condition: string;
  timezone: string;
  hourly: HourCell[];
  /** Every remaining hour of TODAY — what the look is planned against. */
  restOfDay: HourCell[];
  highC: number;
  lowC: number;
} {
  const cur = bundle.current.data?.[0];
  const offset = bundle.current.timezone_offset ?? bundle.hourly.timezone_offset ?? 0;
  const now = nowDt ?? cur?.dt ?? 0;

  const nowC = Math.round(scalarTemp(cur?.temp) ?? 0);
  const cells = bundle.hourly.data ?? [];

  /**
   * The hour CONTAINING now, not the next one. At 07:41 the user is living in
   * the 07:00 cell, and labelling 08:00 as "Now" would be wrong on screen.
   */
  const after = cells.findIndex((c) => c.dt > now);
  const nowIdx = after === -1 ? Math.max(0, cells.length - 1) : Math.max(0, after - 1);

  const toCell = (c: OwmCell, isNow: boolean): HourCell => ({
    hh: localParts(c.dt, offset).hh,
    tempC: Math.round(scalarTemp(c.temp) ?? 0),
    rain: isRainId(idOf(c)),
    isNow,
  });

  const hourly: HourCell[] = [];
  for (let k = 0; k < 4 && nowIdx + k < cells.length; k++) {
    hourly.push(toCell(cells[nowIdx + k], k === 0));
  }

  /**
   * The rest of TODAY, hour by hour.
   *
   * ⚠️ Restricted to the current LOCAL date on purpose. The 20-hour window runs
   * past midnight, and an "evening" window matched on hour-of-day alone would
   * happily plan against TOMORROW's 19:00 — the bug `open-meteo.ts` documents,
   * carried over intact because the hazard is identical.
   */
  const today = cells.length ? localParts(cells[nowIdx].dt, offset).date : "";
  const restOfDay: HourCell[] = [];
  for (let i = nowIdx; i < cells.length; i++) {
    if (localParts(cells[i].dt, offset).date !== today) break;
    restOfDay.push(toCell(cells[i], restOfDay.length === 0));
  }

  /**
   * The peak and trough STILL AHEAD, not the calendar day's — opening the app at
   * 20:00 must not plan against a 17:00 peak that has been and gone.
   */
  const ahead = restOfDay.map((h) => h.tempC);
  const high = ahead.length ? Math.max(...ahead) : nowC;
  const low = ahead.length ? Math.min(...ahead) : nowC;

  return {
    tempC: nowC,
    feelsLikeC: Math.round(
      (typeof cur?.feels_like === "number" ? cur.feels_like : cur?.feels_like?.day) ?? nowC,
    ),
    condition: conditionFor(idOf(cur ?? {ic: 0} as unknown as OwmCell)),
    timezone: bundle.current.timezone ?? bundle.hourly.timezone ?? "UTC",
    hourly,
    restOfDay,
    // Never let the range contradict the reading the user can see on screen.
    highC: Math.max(nowC, high),
    lowC: Math.min(nowC, low),
  };
}

/** Map `timeline/1day` into one `Weather` per requested date. */
export function mapOneCallDaily(daily: OwmResponse, dates: string[]): TripForecast {
  const offset = daily.timezone_offset ?? 0;
  const rows = daily.data ?? [];

  const known = new Map<string, Weather>();
  let lastDate = "";
  for (const row of rows) {
    const t = typeof row.temp === "object" ? row.temp : undefined;
    if (t?.max == null || t?.min == null) continue;
    const { date } = localParts(row.dt, offset);
    known.set(date, {
      // The look is built for the day's HIGH — the cold end is handled by
      // advice, not by putting a coat in every flat-lay. Same rule as the drop.
      tempC: Math.round(t.max),
      highC: Math.round(t.max),
      lowC: Math.round(t.min),
      rain: isRainId(idOf(row)),
    });
    lastDate = date;
  }

  const byDate: Record<string, Weather> = {};
  let beyondHorizon = false;
  // The furthest day we actually have — the nearest real data rather than an
  // invented average, for anything past the horizon.
  const lastKnown = lastDate ? known.get(lastDate) : undefined;

  for (const date of dates) {
    const hit = known.get(date);
    if (hit) {
      byDate[date] = hit;
      continue;
    }
    beyondHorizon = true;
    byDate[date] = lastKnown ?? { tempC: 15, highC: 18, lowC: 11, rain: false };
  }

  return { byDate, beyondHorizon };
}

import { describe, expect, test, vi } from "vitest";
import { cachedSeries, WEATHER_MAX_AGE_H, type CacheStore, type CachedDay } from "../cache";
import hourlyFixture from "./fixtures/onecall-1h.json";
import dailyFixture from "./fixtures/onecall-1day.json";

const LAT = 52.52;
const LON = 13.41;
/** The fixture's own first local date, and the nine that follow it. */
const D0 = "2026-08-28";
const TEN_DAYS = Array.from({ length: 10 }, (_, i) => {
  const d = new Date(`${D0}T00:00:00Z`);
  d.setUTCDate(d.getUTCDate() + i);
  return d.toISOString().slice(0, 10);
});
const NOW = new Date("2026-08-28T07:41:43Z");

/** An in-memory stand-in for the Postgres table, so the logic is testable alone. */
function fakeStore(seed: { day: string; payload: CachedDay; fetchedAt: Date }[] = []) {
  const rows = new Map(seed.map((r) => [r.day, { payload: r.payload, fetchedAt: r.fetchedAt }]));
  const store: CacheStore & { rows: typeof rows; writes: number } = {
    rows,
    writes: 0,
    async read(_lat, _lon, dates) {
      const hit = new Map<string, { payload: CachedDay; fetchedAt: Date }>();
      for (const d of dates) {
        const r = rows.get(d);
        if (r) hit.set(d, r);
      }
      return hit;
    },
    async write(entries) {
      store.writes += 1;
      // `on conflict do nothing` — first writer wins, exactly like the table.
      for (const e of entries) if (!rows.has(e.day)) rows.set(e.day, { payload: e.payload, fetchedAt: e.fetchedAt });
    },
  };
  return store;
}

function fetchers() {
  const daily = vi.fn(async () => dailyFixture);
  const hourly = vi.fn(async () => hourlyFixture);
  return { daily, hourly };
}

describe("cachedSeries — the read-through cache", () => {
  test("a miss calls each fetcher ONCE and stores the mapped series", async () => {
    const store = fakeStore();
    const f = fetchers();
    const out = await cachedSeries({ lat: LAT, lon: LON, dates: [D0], store, ...f, now: NOW });

    expect(f.daily).toHaveBeenCalledTimes(1);
    expect(f.hourly).toHaveBeenCalledTimes(1);
    expect(out.get(D0)!.daily).not.toBeNull();
    expect(out.get(D0)!.hourly.length).toBeGreaterThan(0);
    // The stored payload is OUR shape, never the provider's raw response.
    expect(store.rows.get(D0)!.payload).not.toHaveProperty("timezone_offset");
    expect(store.rows.get(D0)!.payload.timezoneOffset).toBe(7200);
  });

  test("a hit does NOT call the fetchers", async () => {
    const store = fakeStore();
    const first = fetchers();
    await cachedSeries({ lat: LAT, lon: LON, dates: [D0], store, ...first, now: NOW });

    const second = fetchers();
    await cachedSeries({ lat: LAT, lon: LON, dates: [D0], store, ...second, now: NOW });
    expect(second.daily).not.toHaveBeenCalled();
    expect(second.hourly).not.toHaveBeenCalled();
  });

  /**
   * ⚠️ THE ENTIRE ECONOMIC CASE FOR THIS DESIGN. One Call returns 10 daily
   * blocks in ONE response, so a ten-day trip must cost ONE call, not ten.
   * Assert it — the plan's own verification step tested only a single day and
   * would have missed this by a factor of ten.
   */
  test("ONE fetch fills every day it covers — a 10-day trip costs one call", async () => {
    const store = fakeStore();
    const f = fetchers();
    const out = await cachedSeries({ lat: LAT, lon: LON, dates: TEN_DAYS, store, ...f, now: NOW });

    expect(f.daily).toHaveBeenCalledTimes(1);
    expect(out.size).toBe(10);
    expect(store.rows.size).toBe(10);
    // And a second trip over the same window is free.
    const g = fetchers();
    await cachedSeries({ lat: LAT, lon: LON, dates: TEN_DAYS, store, ...g, now: NOW });
    expect(g.daily).not.toHaveBeenCalled();
  });

  test("two users in the same city on the same day cause ONE fetch", async () => {
    const store = fakeStore();
    const f = fetchers();
    await cachedSeries({ lat: LAT, lon: LON, dates: [D0], store, ...f, now: NOW });
    await cachedSeries({ lat: LAT, lon: LON, dates: [D0], store, ...f, now: NOW });
    expect(f.daily).toHaveBeenCalledTimes(1);
  });

  /**
   * ⚠️ A city waking up at 08:00 IS the concurrent case, and a crash there is a
   * blank weather strip for everyone in it.
   */
  test("two concurrent misses for the same key do not throw", async () => {
    const store = fakeStore();
    const f = fetchers();
    const both = await Promise.all([
      cachedSeries({ lat: LAT, lon: LON, dates: [D0], store, ...f, now: NOW }),
      cachedSeries({ lat: LAT, lon: LON, dates: [D0], store, ...f, now: NOW }),
    ]);
    expect(both[0].get(D0)).toBeDefined();
    expect(both[1].get(D0)).toBeDefined();
    expect(store.rows.size).toBe(10);
  });

  /**
   * ⚠️ A day-old temperature is a far better outcome than a screen with no
   * weather at all.
   */
  test("a fetcher failure falls back to the STALE row rather than throwing", async () => {
    const stale: CachedDay = {
      timezone: "Europe/Berlin",
      timezoneOffset: 7200,
      hourly: [{ dt: 1787893200, temp: 11.1, feelsLike: 10, conditionId: 800 }],
      daily: { dt: 1787875200, max: 12, min: 4, conditionId: 800 },
    };
    const store = fakeStore([
      { day: D0, payload: stale, fetchedAt: new Date(NOW.getTime() - 48 * 3600_000) },
    ]);
    const boom = async () => {
      throw new Error("openweather down");
    };
    const out = await cachedSeries({
      lat: LAT, lon: LON, dates: [D0], store, daily: boom, hourly: boom, now: NOW,
    });
    expect(out.get(D0)!.daily!.max).toBe(12); // the stale row, served
  });

  test("a fetcher failure with NO stale row yields no entry rather than throwing", async () => {
    const boom = async () => {
      throw new Error("openweather down");
    };
    const out = await cachedSeries({
      lat: LAT, lon: LON, dates: [D0], store: fakeStore(), daily: boom, hourly: boom, now: NOW,
    });
    expect(out.get(D0)).toBeUndefined();
  });

  /**
   * ⚠️ `fetched_at` exists for this. A row written at 06:00 is an 18-hour-old
   * prediction by midnight.
   */
  test("a row older than WEATHER_MAX_AGE_H is refetched", async () => {
    const store = fakeStore();
    await cachedSeries({ lat: LAT, lon: LON, dates: [D0], store, ...fetchers(), now: NOW });

    const later = new Date(NOW.getTime() + (WEATHER_MAX_AGE_H + 1) * 3600_000);
    const f = fetchers();
    await cachedSeries({ lat: LAT, lon: LON, dates: [D0], store, ...f, now: later });
    expect(f.daily).toHaveBeenCalledTimes(1);
  });

  test("a row INSIDE the freshness window is not refetched", async () => {
    const store = fakeStore();
    await cachedSeries({ lat: LAT, lon: LON, dates: [D0], store, ...fetchers(), now: NOW });

    const soon = new Date(NOW.getTime() + (WEATHER_MAX_AGE_H - 1) * 3600_000);
    const f = fetchers();
    await cachedSeries({ lat: LAT, lon: LON, dates: [D0], store, ...f, now: soon });
    expect(f.daily).not.toHaveBeenCalled();
  });

  /**
   * ⚠️ `roundCoord` (2dp ≈ 1.1km) exists precisely so everyone in one city
   * produces the same key. If the cache did not round, every GPS reading would
   * be a fresh miss and the whole design would be decorative.
   */
  test("nearby coordinates collapse to the same cache key", async () => {
    const store = fakeStore();
    const f = fetchers();
    await cachedSeries({ lat: 52.5201, lon: 13.4099, dates: [D0], store, ...f, now: NOW });
    await cachedSeries({ lat: 52.5234, lon: 13.4051, dates: [D0], store, ...f, now: NOW });
    expect(f.daily).toHaveBeenCalledTimes(1);
  });
});

import { roundCoord } from "./location";
import { localParts, DAILY_MAX } from "./openweather";

/**
 * The read-through weather cache.
 *
 * ⚠️ **Calls scale with CITIES per day, not with users.** That is the whole
 * point: `roundCoord` (2dp ≈ 1.1km) normalises the key at the boundary so every
 * caller in one place produces the same row.
 *
 * ⚠️ **Postgres, not `next: { revalidate }`.** The Data Cache is per-deployment,
 * not guaranteed shared across instances, and gone on redeploy — Decision 6
 * records the sibling trap where `use cache` dies with the instance. This is
 * also where the Redis question already landed: rejected, because Postgres
 * already IS the cache.
 *
 * ⚠️ **The cache must NEVER be exposed as an endpoint.** ODbL ShareAlike
 * attaches to a weather dataset or API made available outside the organisation.
 * Internal caching is fine; a public route over it is not.
 */

/**
 * ⚠️ ONE CALL 4.0 COSTS THREE ENDPOINTS, NOT ONE — `current`, `timeline/1h` and
 * `timeline/1day` — where 3.0 returned all three blocks in a single payload.
 * The naive shape is therefore 3 calls per city per day (≈333 cities on the
 * 1,000/day free tier).
 *
 * ⚠️ **This module deliberately makes it TWO, by dropping the `current` call.**
 * That is not an optimisation; it is the only design that satisfies both of the
 * plan's own constraints at once:
 *
 *   - `current` CANNOT be cached per-day — the pill would show the 08:00
 *     reading at 18:00, which the plan calls out explicitly.
 *   - `current` CANNOT be fetched per-request either — then calls scale with
 *     USERS, which is the entire thing this cache exists to prevent.
 *
 * There is no third option, so the current reading is derived from the HOURLY
 * cell containing now (`mapOneCall` already picks it, and marks it `isNow`).
 * Measured on the capture fixture the two agree to 0.04°C — 18.81 against 18.85,
 * indistinguishable after `Math.round` — and the derived value has the property
 * the cached one cannot: it moves through the day without another call.
 *
 * ⚠️ **To go back to 3 calls** (a true nowcast on the pill), fetch
 * `/onecall/current` per request and merge it over the derived reading. Expect
 * calls to scale with users again, and budget accordingly.
 */
export const CALLS_PER_CITY_PER_DAY = 2;

/**
 * How old a row may be before it is refetched.
 *
 * ⚠️ Presence is not freshness: a row written at 06:00 is an 18-hour-old
 * prediction by midnight. Six hours caps that at ~4 calls per city per day
 * (≈250 cities free) while keeping an afternoon forecast that was made this
 * morning rather than yesterday.
 */
export const WEATHER_MAX_AGE_H = 6;

/**
 * The TIME-INVARIANT series for one place and one local day.
 *
 * ⚠️ NOT `mapForecast`'s output. Every field that mapper returns depends on the
 * moment of asking — high/low are deliberately the peak still AHEAD, not the
 * calendar day's — so caching a collapsed payload for a day would plan an
 * evening look against a peak that had already passed. Store the series; derive
 * the view per request.
 *
 * ⚠️ Our shape, never the provider's. A future swap should touch one adapter,
 * not every reader.
 */
export type CachedDay = {
  timezone: string;
  timezoneOffset: number;
  hourly: { dt: number; temp: number; feelsLike: number; conditionId: number }[];
  daily: { dt: number; max: number; min: number; conditionId: number } | null;
};

export type CacheStore = {
  read(lat: number, lon: number, dates: string[]): Promise<Map<string, { payload: CachedDay; fetchedAt: Date }>>;
  write(entries: { lat: number; lon: number; day: string; payload: CachedDay; fetchedAt: Date }[]): Promise<void>;
};

type RawResponse = {
  timezone?: string;
  timezone_offset?: number;
  data?: {
    dt: number;
    temp?: number | { min?: number; max?: number };
    feels_like?: number | { day?: number };
    weather?: { id: number }[];
  }[];
};

/** Group one raw `1day` + one raw `1h` response into per-local-date series. */
function toSeries(daily: RawResponse | null, hourly: RawResponse | null): Map<string, CachedDay> {
  const timezone = daily?.timezone ?? hourly?.timezone ?? "UTC";
  const offset = daily?.timezone_offset ?? hourly?.timezone_offset ?? 0;
  const out = new Map<string, CachedDay>();

  const blank = (): CachedDay => ({ timezone, timezoneOffset: offset, hourly: [], daily: null });

  for (const row of daily?.data ?? []) {
    const t = typeof row.temp === "object" ? row.temp : undefined;
    if (t?.max == null || t?.min == null) continue;
    const { date } = localParts(row.dt, offset);
    const entry = out.get(date) ?? blank();
    entry.daily = { dt: row.dt, max: t.max, min: t.min, conditionId: row.weather?.[0]?.id ?? 800 };
    out.set(date, entry);
  }

  for (const row of hourly?.data ?? []) {
    const { date } = localParts(row.dt, offset);
    const entry = out.get(date) ?? blank();
    entry.hourly.push({
      dt: row.dt,
      temp: typeof row.temp === "number" ? row.temp : 0,
      feelsLike: typeof row.feels_like === "number" ? row.feels_like : 0,
      conditionId: row.weather?.[0]?.id ?? 800,
    });
    out.set(date, entry);
  }

  return out;
}

/**
 * Read the series for `dates`, fetching only what is missing or stale.
 *
 * One fetch fills EVERY day it covers — One Call returns up to `DAILY_MAX` daily
 * blocks in a single response, so a ten-day trip costs one call, not ten. That
 * fan-out is the economic case for this design and it is asserted in the tests.
 */
export async function cachedSeries(args: {
  lat: number;
  lon: number;
  dates: string[];
  store: CacheStore;
  daily: () => Promise<unknown>;
  hourly: () => Promise<unknown>;
  now?: Date;
}): Promise<Map<string, CachedDay>> {
  const { dates, store } = args;
  const lat = roundCoord(args.lat);
  const lon = roundCoord(args.lon);
  const now = args.now ?? new Date();
  if (dates.length === 0) return new Map();

  const cached = await store.read(lat, lon, dates);

  const cutoff = now.getTime() - WEATHER_MAX_AGE_H * 3600_000;
  const fresh = new Map<string, CachedDay>();
  const stale = new Map<string, CachedDay>();
  for (const [day, row] of cached) {
    (row.fetchedAt.getTime() >= cutoff ? fresh : stale).set(day, row.payload);
  }

  const missing = dates.filter((d) => !fresh.has(d));
  if (missing.length === 0) return fresh;

  let fetched: Map<string, CachedDay>;
  try {
    // Both in flight together — they are independent endpoints.
    const [d, h] = await Promise.all([args.daily(), args.hourly()]);
    fetched = toSeries(d as RawResponse, h as RawResponse);
  } catch {
    /**
     * ⚠️ Serve the stale row rather than throwing. A day-old temperature is a
     * far better outcome than a screen with no weather — and a date we have
     * never seen simply stays absent, which callers already handle as
     * `beyondHorizon`.
     */
    return new Map([...stale, ...fresh]);
  }

  if (fetched.size > 0) {
    /**
     * ⚠️ `on conflict do nothing`, and the write is deliberately NOT awaited
     * into the failure path: a city waking up at 08:00 is the concurrent case,
     * and a lost race there must not blank the strip for whoever lost it.
     */
    try {
      await store.write(
        [...fetched].slice(0, DAILY_MAX).map(([day, payload]) => ({ lat, lon, day, payload, fetchedAt: now })),
      );
    } catch {
      // The data is in hand; failing to memoise it is not a reason to fail the read.
    }
  }

  const out = new Map<string, CachedDay>(fresh);
  for (const [day, payload] of fetched) out.set(day, payload);
  // Anything still absent falls back to a stale row if we have one.
  for (const [day, payload] of stale) if (!out.has(day)) out.set(day, payload);
  return out;
}

